package com.example.cinematicscenes.event; import com.example.cinematicscenes.camera.Easing; import com.example.cinematicscenes.scene.SceneContext; import net.minecraft.world.phys.Vec3; public record CameraMoveEvent(Vec3 position,float yaw,float pitch,float fov,int ticks,Easing easing) implements SceneEvent { public void start(SceneContext c){c.camera.moveTo(position,yaw,pitch,fov,ticks,easing);} public void update(SceneContext c,float p){} public void finish(SceneContext c){} }
